import os
import re
from typing import List, Optional


class Note:
    """Represents a single note."""

    def __init__(self, note_id: int, title: str, body: str, created_at: float):
        self.id = note_id
        self.title = title
        self.body = body
        self.created_at = created_at

    def __repr__(self) -> str:
        return f"Note(id={self.id}, title={self.title!r})"


class NoteStore:
    """Manages notes stored as Markdown files in a local directory."""

    def __init__(self, notes_dir: str = "notes"):
        self.notes_dir = notes_dir
        os.makedirs(self.notes_dir, exist_ok=True)

    def _path(self, note_id: int) -> str:
        return os.path.join(self.notes_dir, f"{note_id:04d}.md")

    def _next_id(self) -> int:
        """Determine the next available note ID."""
        existing = []
        try:
            for fname in os.listdir(self.notes_dir):
                match = re.match(r"^(\d+)\.md$", fname)
                if match:
                    existing.append(int(match.group(1)))
        except FileNotFoundError:
            pass
        return max(existing) + 1 if existing else 1

    def _read_note(self, note_id: int) -> Optional[Note]:
        """Read a single note from disk. Returns None if it doesn't exist."""
        path = self._path(note_id)
        if not os.path.isfile(path):
            return None
        try:
            with open(path, "r", encoding="utf-8") as f:
                content = f.read()
        except (OSError, IOError) as e:
            raise IOError(f"Failed to read note {note_id}: {e}") from e

        lines = content.split("\n")
        title = lines[0].strip() if lines else ""
        # body starts from line 3 (index 2), skipping empty line at index 1
        body = "\n".join(lines[2:]).strip() if len(lines) > 2 else ""
        mtime = os.path.getmtime(path)
        return Note(note_id, title, body, mtime)

    def create(self, title: str, body: str) -> Note:
        """Create a new note and persist it to disk."""
        note_id = self._next_id()
        path = self._path(note_id)
        content = f"{title}\n\n{body}\n" if body else f"{title}\n\n"
        try:
            with open(path, "w", encoding="utf-8") as f:
                f.write(content)
        except (OSError, IOError) as e:
            raise IOError(f"Failed to write note {note_id}: {e}") from e
        mtime = os.path.getmtime(path)
        return Note(note_id, title, body, mtime)

    def list_notes(self) -> List[Note]:
        """Return all notes sorted by ID."""
        notes: List[Note] = []
        try:
            for fname in sorted(os.listdir(self.notes_dir)):
                match = re.match(r"^(\d+)\.md$", fname)
                if match:
                    note_id = int(match.group(1))
                    note = self._read_note(note_id)
                    if note is not None:
                        notes.append(note)
        except FileNotFoundError:
            pass
        return notes

    def search(self, keyword: str) -> List[Note]:
        """Return notes whose title or body contain the keyword (case-insensitive)."""
        keyword_lower = keyword.lower()
        results: List[Note] = []
        for note in self.list_notes():
            if keyword_lower in note.title.lower() or keyword_lower in note.body.lower():
                results.append(note)
        return results

    def get(self, note_id: int) -> Optional[Note]:
        """Retrieve a single note by its ID. Returns None if not found."""
        return self._read_note(note_id)"}
